function namedBlock(source, kind, name) {
  const matches = [...source.matchAll(kind === "path" ? /^  \/[^\n]+:\n/gmu : /^    [A-Za-z0-9]+:\n/gmu)]
  const index = matches.findIndex((item) => item[0] === `${kind === "path" ? "  " : "    "}${name}:\n`)
  if (index < 0) return null
  const end = index + 1 < matches.length ? matches[index + 1].index : kind === "path" ? source.indexOf("components:\n", matches[index].index) : source.length
  return source.slice(matches[index].index, end < 0 ? source.length : end)
}
